public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) {
        String[] replica1 = {"chunk-A-original", "chunk-B-original", "chunk-C-original", "chunk-D-original"};
        String[] replica2 = {"chunk-A-original", "chunk-B-original", "chunk-C-CORRUPTED", "chunk-D-original"};

        long[] h1 = buildLeafHashes(replica1);
        long[] h2 = buildLeafHashes(replica2);

        long ab1 = hashCombine(h1[0], h1[1]);
        long cd1 = hashCombine(h1[2], h1[3]);
        long root1 = hashCombine(ab1, cd1);

        long ab2 = hashCombine(h2[0], h2[1]);
        long cd2 = hashCombine(h2[2], h2[3]);
        long root2 = hashCombine(ab2, cd2);

        if (root1 == root2) {
            System.out.println("Root hashes match, replicas are fully in sync");
            return;
        }
        System.out.println("Root hashes mismatch, comparing subtrees");

        if (ab1 == ab2) {
            System.out.println("Left subtree (A, B) matches, skipped entirely, no need to check A or B individually");
        }
        if (cd1 != cd2) {
            System.out.println("Right subtree (C, D) mismatches, descending only into this side");
            if (h1[2] != h2[2]) {
                System.out.println("Chunk C is corrupted");
            }
            if (h1[3] == h2[3]) {
                System.out.println("Chunk D matches, confirmed fine");
            }
        }
    }

    static long[] buildLeafHashes(String[] chunks) {
        long[] hashes = new long[chunks.length];
        for (int i = 0; i < chunks.length; i++) {
            hashes[i] = djb2Hash(chunks[i]);
        }
        return hashes;
    }

    static long djb2Hash(String s) {
        long hash = 5381;
        for (int i = 0; i < s.length(); i++) {
            hash = ((hash * 33) + s.charAt(i)) % MOD;
        }
        return hash;
    }

    static long hashCombine(long left, long right) {
        return djb2Hash(left + "|" + right);
    }
}

