def djb2_hash(s):
    hash_value = 5381
    for ch in s:
        hash_value = ((hash_value * 33) + ord(ch)) % MOD
    return hash_value


def hash_combine(left, right):
    return djb2_hash(f"{left}|{right}")


def build_leaf_hashes(chunks):
    return [djb2_hash(chunk) for chunk in chunks]


