#include <iostream>
#include <string>
#include <vector>
using namespace std;

const long long MOD = 1000000007LL;

long long djb2Hash(const string& s) {
    long long hash = 5381;
    for (char c : s) {
        hash = ((hash * 33) + static_cast<unsigned char>(c)) % MOD;
    }
    return hash;
}

long long hashCombine(long long left, long long right) {
    return djb2Hash(to_string(left) + "|" + to_string(right));
}

vector<long long> buildLeafHashes(const vector<string>& chunks) {
    vector<long long> hashes;
    for (const auto& chunk : chunks) {
        hashes.push_back(djb2Hash(chunk));
    }
    return hashes;
}

int main() {
    vector<string> replica1 = {"chunk-A-original", "chunk-B-original", "chunk-C-original", "chunk-D-original"};
    vector<string> replica2 = {"chunk-A-original", "chunk-B-original", "chunk-C-CORRUPTED", "chunk-D-original"};

    vector<long long> h1 = buildLeafHashes(replica1);
    vector<long long> h2 = buildLeafHashes(replica2);

    long long ab1 = hashCombine(h1[0], h1[1]);
    long long cd1 = hashCombine(h1[2], h1[3]);
    long long root1 = hashCombine(ab1, cd1);

    long long ab2 = hashCombine(h2[0], h2[1]);
    long long cd2 = hashCombine(h2[2], h2[3]);
    long long root2 = hashCombine(ab2, cd2);

    if (root1 == root2) {
        cout << "Root hashes match, replicas are fully in sync" << endl;
        return 0;
    }
    cout << "Root hashes mismatch, comparing subtrees" << endl;

    if (ab1 == ab2) {
        cout << "Left subtree (A, B) matches, skipped entirely, no need to check A or B individually" << endl;
    }
    if (cd1 != cd2) {
        cout << "Right subtree (C, D) mismatches, descending only into this side" << endl;
        if (h1[2] != h2[2]) {
            cout << "Chunk C is corrupted" << endl;
        }
        if (h1[3] == h2[3]) {
            cout << "Chunk D matches, confirmed fine" << endl;
        }
    }

    return 0;
}
